h1 {
  text-align: center;
  color: #8B2E2E;
  margin-bottom: 20px;
}
#list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.card {
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 8px;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: #3D2B1F;
  font-size: 16px;
}
.num {
  background: #8B2E2E;
  color: #fff;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
}

starter.js:
// 作曲家数组
let composers = ["巴赫", "莫扎特", "贝多芬", "肖邦", "德彪西"];
// 用 forEach 循环生成 HTML
let html = "";
composers.forEach(function(name, index) {
  html += `
    <div class="card">
      <span class="num">${index + 1}</span>
      ${name}
    </div>
  `;
});
// 显示到页面上
document.querySelector("#list").innerHTML = html;
